void ServiceHandlerAsyncWaiter::GetPurchasedState(
    PurchasedInfoPtr* out_state) {
  base::RunLoop loop;
  proxy_->GetPurchasedState(
      base::BindOnce(
          [](base::RunLoop* loop,
             PurchasedInfoPtr* out_state
,
             PurchasedInfoPtr state) {*out_state = std::move(state);
            loop->Quit();
          },
          &loop,
          out_state));
  loop.Run();
}

PurchasedInfoPtr ServiceHandlerAsyncWaiter::GetPurchasedState(
    ) {
  PurchasedInfoPtr async_wait_result;
  GetPurchasedState(&async_wait_result);
  return async_wait_result;
}

